// tcp_server.c - simple TCP/IP server (IPv4) in C (POSIX)
// Build: gcc -O2 -Wall -Wextra -o tcp_server tcp_server.c
// Run:   ./tcp_server 8080

#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

static void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    int port = 8080;
    if (argc > 1) port = atoi(argv[1]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port\n");
        return EXIT_FAILURE;
    }

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) die("socket");

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0)
        die("setsockopt(SO_REUSEADDR)");

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY); // listen on all interfaces
    addr.sin_port = htons((uint16_t)port);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0)
        die("bind");

    if (listen(server_fd, 16) < 0)
        die("listen");

    printf("Listening on port %d...\n", port);

    for (;;) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);

        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            die("accept");
        }

        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        printf("Client connected: %s:%d\n", ip, ntohs(client_addr.sin_port));

        // Simple echo loop
        char buf[4096];
        for (;;) {
            ssize_t n = recv(client_fd, buf, sizeof(buf), 0);
            if (n == 0) {
                // client closed
                break;
            } else if (n < 0) {
                perror("recv");
                break;
            }

            // Echo back what we received
            ssize_t sent = 0;
            while (sent < n) {
                ssize_t m = send(client_fd, buf + sent, (size_t)(n - sent), 0);
                if (m < 0) {
                    perror("send");
                    goto done_client;
                }
                sent += m;
            }
        }

    done_client:
        printf("Client disconnected\n");
        close(client_fd);
    }

    close(server_fd);
    return 0;
}
